/* Social forces: practical guide data (families, signs, counter-moves, symptoms) */
window.FGUIDE = {
hidden:["org_silence"], /* merged into spiral_silence */
families:[
  {id:"copying", name:"Copying each other", text:"People look to others before they decide, so early or visible choices spread.", forces:["cascade","conformity","cumulative","coordination"]},
  {id:"quiet", name:"Staying quiet", text:"What people think and what the group hears drift apart, because speaking up feels risky or pointless.", forces:["spiral_silence","pluralistic_ignorance","mum_effect","exit_voice"]},
  {id:"connected", name:"Who is connected", text:"Who talks to whom, and who knows what, shapes what reaches the decision.", forces:["influence_few","network_shape","homophily","message_drift","local_knowledge","shared_info"]},
  {id:"mood", name:"Group mood and commitment", text:"How a group feels about itself, its past choices and its process changes how well it decides.", forces:["independent","groupthink","polarization","commitment","diffusion","blame_avoidance","zone_acceptance","accountability","fair_process"]}
],
groups:[{"id": "pos", "name": "Mostly positive", "text": "Forces you want more of.", "rows": [{"s": "People accepted the decision, even those who lost, because they understood how it was made.", "f": ["fair_process"]}, {"s": "Everyone did the same thing without being told, because each expected the others to.", "f": ["coordination"]}, {"s": "The people closest to the problem were asked, and it changed the plan.", "f": ["local_knowledge"]}, {"s": "Knowing they would have to explain it, people checked their reasoning.", "f": ["accountability"]}, {"s": "People followed the decision without debate, because it was clearly the decider's call.", "f": ["zone_acceptance"]}]}, {"id": "two", "name": "Two-sided", "text": "The same force helps in one setting and hurts in another.", "rows": [{"s": "Everyone formed a view before hearing anyone else's, and the views were combined.", "f": ["independent"], "e": "helps"}, {"s": "One person judged alone, without what others knew.", "f": ["independent"], "e": "hurts"}, {"s": "Everyone had the same facts, so the debate was about choices.", "f": ["shared_info"], "e": "helps"}, {"s": "Everyone made the same mistake, because everyone relied on the same information.", "f": ["shared_info"], "e": "hurts"}, {"s": "The person who knew most was listened to most.", "f": ["influence_few"], "e": "helps"}, {"s": "The same few people always end up deciding.", "f": ["influence_few"], "e": "hurts"}, {"s": "News of the decision reached everyone at the same time.", "f": ["network_shape"], "e": "helps"}, {"s": "Some people heard about the decision long after others.", "f": ["network_shape"], "e": "hurts"}, {"s": "Newcomers quickly picked up how things are done here.", "f": ["conformity"], "e": "helps"}, {"s": "No one questioned the routine, even after it stopped working.", "f": ["conformity"], "e": "hurts"}, {"s": "Talking it through gave the group a clear, shared position.", "f": ["polarization"], "e": "helps"}, {"s": "The group came out more extreme than anyone went in.", "f": ["polarization"], "e": "hurts"}, {"s": "A good idea gained support as more people joined in.", "f": ["cumulative"], "e": "helps"}, {"s": "An early favourite kept winning, even after better options appeared.", "f": ["cumulative"], "e": "hurts"}, {"s": "People who think alike worked quickly and trusted each other.", "f": ["homophily"], "e": "helps"}, {"s": "The same circle of people ran everything, and others felt shut out.", "f": ["homophily"], "e": "hurts"}, {"s": "We stuck with the plan through a hard start, and it paid off.", "f": ["commitment"], "e": "helps"}, {"s": "We keep defending a plan that isn't working.", "f": ["commitment"], "e": "hurts"}, {"s": "People followed those who knew the way, and the whole group got there quickly.", "f": ["cascade"], "e": "helps"}, {"s": "The first person to speak set the direction for everyone.", "f": ["cascade"], "e": "hurts"}]}, {"id": "neg", "name": "Mostly harmful", "text": "Forces to watch for and counter.", "rows": [{"s": "Everyone agreed in the meeting, but nothing changed afterwards.", "f": ["pluralistic_ignorance"]}, {"s": "People complain in the corridor but not in meetings.", "f": ["spiral_silence"]}, {"s": "Unhappy staff or families quietly left instead of complaining.", "f": ["exit_voice"]}, {"s": "A risky plan went through with no doubts raised.", "f": ["groupthink"]}, {"s": "Bad news reached the head too late, or softened.", "f": ["mum_effect"]}, {"s": "By the time the decision reached parents, it meant something different.", "f": ["message_drift"]}, {"s": "Everyone assumed someone else would deal with it.", "f": ["diffusion"]}, {"s": "We hid behind policy, or someone junior took the blame.", "f": ["blame_avoidance"]}]}],
clusters:{"neg": [["Staying quiet", ["pluralistic_ignorance", "spiral_silence", "exit_voice"]], ["Following others", ["groupthink"]], ["What reaches the top", ["mum_effect", "message_drift"]], ["Nobody owns it", ["diffusion", "blame_avoidance"]]], "two": [["Who knows what", ["independent", "shared_info", "network_shape", "homophily"]], ["Who we follow", ["influence_few", "conformity", "cumulative", "cascade"]], ["Mood and momentum", ["polarization", "commitment"]]], "pos": [["Hearing everyone", ["local_knowledge"]], ["Owning the decision", ["fair_process", "accountability"]], ["Moving together", ["coordination", "zone_acceptance"]]]},
lesson:{"independent": {"scenes": [{"tone": "good", "case": "Delphi method", "text": "A group of heads had to forecast how many Year 7 places would be needed next year. Each made a first forecast alone, without seeing anyone else's. Some guessed high and some low, each for their own reasons, so the average of their first forecasts was already a sensible number."}, {"tone": "bad", "case": "One person decides (autocratic)", "text": "When the swimming coach quit and money was tight, the head of activities cancelled swimming for the year on his own. He didn't ask the teachers or students it would affect, and both felt the effects all year."}], "mech": "Every judgement mixes some real knowledge with some error. When many people judge alone and their views are then combined, their errors are their own: one head guesses high because of a new housing estate, another low because of a falling birth rate, and together the errors partly cancel while the knowledge adds up. Independent judgment is about how people form a view: alone, before they hear anyone else. It helps when there are many separate views to combine. The head of activities also judged alone, but his was the only view. There was nothing to cancel his mistake, and what teachers knew never reached him. Local knowledge was ignored too, which is often how a single judgment goes wrong.", "ice": [{"tone": "good", "layers": [["What everyone sees", "The first forecasts are spread out, and their average is a sensible number."], ["The pattern over time", "Some guess high and some low, each for their own reasons, so the errors partly cancel."], ["The structure causing it", "Each person forecasts alone, before seeing anyone else's number."], ["The belief holding it in place", "“My own view is worth giving, even if it differs from others.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "Swimming is cancelled for the year."], ["The pattern over time", "Teachers and students deal with effects no one foresaw."], ["The structure causing it", "One person judges alone, with no route for what others know."], ["The belief holding it in place", "“It's a budget call, and budgets are mine.”"]]}], "why": "In 1907 Francis Galton collected 787 guesses of an ox's weight at a country fair. No single guess was reliable, but the middle guess was within 1% of the true weight. A century later, Lorenz and colleagues showed the other side: once people could see each other's estimates, their answers bunched together and the group grew more confident, without becoming any more accurate. James Surowiecki, drawing on studies like these, argued that a crowd is wise only when its judgments are independent, varied and then combined. A single independent judgment has none of those protections.", "remember": "Collect views separately, then combine them. Don't let one separate view stand alone."}, "shared_info": {"scenes": [{"tone": "good", "case": "Open assembly (Gram Sabha)", "text": "A department had to cut its budget. Every teacher saw the full figures and the cost of each option before the meeting. The argument was about which cut to make, not about whether numbers were being hidden, and teachers who lost out could see why."}, {"tone": "bad", "case": "Delphi method", "text": "A panel forecast school places across a region. Most members drew on the same national data and the same research. Round after round they agreed more strongly, and the forecast was wrong for the rural schools, which no one on the panel knew well."}], "mech": "Shared information is about what people know, not how they form a view. In the budget meeting, everyone seeing the same figures moved the argument from what is true to what to do, and made the result easier to accept. On the forecasting panel, each member did judge separately, but they all judged from the same data. So their mistakes lined up instead of cancelling, and agreement grew exactly where the panel was weakest. The panel also lacked anyone from the rural schools, so this is partly a problem of local knowledge too.", "ice": [{"tone": "good", "layers": [["What everyone sees", "The department agrees a budget cut, and those who lose out accept it."], ["The pattern over time", "The debate stays on choices, not on whether figures are hidden."], ["The structure causing it", "Everyone gets the full budget and the cost of each option before the meeting."], ["The belief holding it in place", "“We are all working from the same facts.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "The panel agrees more strongly with each round."], ["The pattern over time", "The forecast is wrong for the rural schools."], ["The structure causing it", "Most members use the same national data, and no one knows the rural schools."], ["The belief holding it in place", "“If we all agree, we must be right.”"]]}], "why": "In experiments by Stasser and Titus, groups spent most of their discussion on facts every member already knew, and rarely raised facts only one member knew, even when those were the key to the right answer. Lorenz and colleagues found that people who saw the same information became more confident together without becoming more accurate.", "remember": "Share the facts with everyone, and collect what each person knows."}, "pluralistic_ignorance": {"scenes": [{"tone": "bad", "case": "Polycentric governance", "text": "At a boarding school, the heads of academics, boarding and activities each looked after one part of students' lives and kept their own records. Each noticed a warning sign about the same student. Each saw the other two carrying on as normal, and took that as a sign nothing serious was wrong. Inspectors later found that the student's needs had never been shared."}], "mech": "Each head was privately worried, but judged the situation by what the others were doing, not by what they knew. Because no one acted, everyone looked unconcerned, so each head decided their own worry was probably misplaced. The worry was shared by all three; the calm was not real. Diffusion of responsibility made it worse: with three people responsible, each assumed another was following up.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "All three heads carry on as normal."], ["The pattern over time", "Warning signs about the same student pile up, and nothing is done."], ["The structure causing it", "Three separate records, and no regular meeting where the heads compare notes."], ["The belief holding it in place", "“If it were serious, the others would be doing something.”"]]}], "why": "Prentice and Miller asked Princeton students how comfortable they were with the amount of drinking on campus, and how comfortable they thought the average student was. Most rated themselves less comfortable than they believed others to be. Almost everyone was going along with a view they wrongly thought belonged to everyone else.", "remember": "Others staying calm does not mean nothing is wrong. Say what you have noticed."}, "local_knowledge": {"scenes": [{"tone": "good", "case": "Advice process", "text": "A biology teacher had to choose between two microscopes. Before deciding, she asked the finance officer and a student who repairs lab equipment. The finance officer knew the cheaper model broke often. The student knew which parts fail first. She bought the sturdier model."}], "mech": "The facts that mattered were not in any catalogue. They sat with the people who had paid for repairs and done them. Local knowledge is about where knowledge lives: with the people closest to the work, often outside the usual chain of approval. The teacher did not need everyone's opinion. She needed the two people who had seen the microscopes fail, and she had to go and ask them.", "ice": [{"tone": "good", "layers": [["What everyone sees", "The teacher buys a microscope that lasts."], ["The pattern over time", "Problems are caught before the purchase, not after."], ["The structure causing it", "Anyone can decide, but they must first ask the people who know most."], ["The belief holding it in place", "“The people who use and fix things know things I don't.”"]]}], "why": "Friedrich Hayek argued in 1945 that the knowledge a society needs is never held in one place. Much of it is knowledge of particular times and places, held in small pieces by many people, such as a technician who knows which machine is about to fail. No planner at the centre can collect all of it, so good systems let those pieces shape decisions.", "remember": "Before you decide, ask who has seen this go wrong."}, "fair_process": {"scenes": [{"tone": "good", "case": "One person decides after asking (consultative)", "text": "A head had to choose a reading scheme. She told staff at the start that the decision was hers, and asked each teacher to write down how their weakest readers coped with each scheme. After deciding, she explained which notes had shaped her choice. Teachers whose preferred scheme lost still said they had been heard."}], "mech": "The teachers did not get the outcome they wanted, but they understood how it was reached. They knew from the start who would decide, they had a real way to contribute, and they could see their notes in the reasons. Fair process is about how a decision is made and explained, not who makes it. Here the teachers' local knowledge also improved the decision, but even teachers whose advice lost accepted it, because the process had been open with them.", "ice": [{"tone": "good", "layers": [["What everyone sees", "Teachers whose scheme lost still accept the choice."], ["The pattern over time", "People keep backing decisions they did not want."], ["The structure causing it", "The head says who decides, asks everyone, and explains the choice afterwards."], ["The belief holding it in place", "“I can see how my view was weighed, even though I lost.”"]]}], "why": "John Thibaut and Laurens Walker studied how people judge legal disputes. People rated a procedure fairer, and accepted its verdict more readily, when they had a chance to present their side, even when the verdict went against them. Kim and Mauborgne found the same in companies: people accepted hard decisions when they were involved, the reasons were explained, and what was expected next was clear.", "remember": "Say who decides, ask before you do, and explain the choice afterwards."}, "accountability": {"scenes": [{"tone": "good", "case": "A few decide (committee)", "text": "Senior examiners set the grade boundaries for a national maths exam. They knew the boundaries would be published on results day and that every school would check them. Each examiner judged sample scripts alone before the meeting, and then compared their judgements in the meeting."}], "mech": "The examiners thought more carefully because they knew they would have to explain each choice to people who would check it. That expectation changed how they worked before anyone asked a question. Accountability is about having to answer for a decision afterwards. It works best when the deciders do not know in advance what their audience wants to hear, so the only safe position is a well-reasoned one.", "ice": [{"tone": "good", "layers": [["What everyone sees", "Grade boundaries that schools can check and trust."], ["The pattern over time", "Each examiner judges alone first, then the group compares."], ["The structure causing it", "Boundaries are published, and every school can scrutinise them."], ["The belief holding it in place", "“We will have to explain every choice we make.”"]]}], "why": "Jennifer Lerner and Philip Tetlock reviewed decades of studies on accountability. People think more carefully when they learn, before forming a view, that they will have to explain it to an audience whose views they do not know. When they already know what the audience wants, they tend to give that view instead of thinking harder.", "remember": "Tell people, before they decide, that they will have to explain their choice."}, "coordination": {"scenes": [{"tone": "good", "case": "Lazy consensus", "text": "A teacher posted in the department channel that she planned to swap one Year 10 novel for a newer one, and would order it if no one objected by Friday. Two colleagues replied with a thumbs up and no one objected. She ordered the books on Monday. The department meeting, which usually took 45 minutes of small decisions, took 15."}], "mech": "Everyone knew the rule: silence by Friday means yes. So no one had to guess whether to reply, chase colleagues, or wait for a meeting. Coordination is about people matching what they expect others to do. The department did not need everyone to agree on the novel. It needed everyone to share the same expectation about how small decisions go ahead.", "ice": [{"tone": "good", "layers": [["What everyone sees", "Small changes go ahead without a meeting."], ["The pattern over time", "Meetings get shorter, and objections still come in when they matter."], ["The structure causing it", "A known rule: post the plan, give a deadline, silence means yes."], ["The belief holding it in place", "“Everyone knows how small decisions are made here.”"]]}], "why": "Thomas Schelling asked people where they would meet a stranger in New York if they had agreed a day but not a place or time, and could not contact each other. Most chose Grand Central Station at noon. People who cannot talk can still coordinate when there is an obvious choice they expect others to make too.", "remember": "Make the rule for how decisions go ahead obvious to everyone."}, "zone_acceptance": {"scenes": [{"tone": "good", "case": "Chain of command", "text": "A state health department ran a deworming day through every school. Each head teacher received the same instruction: give one tablet to every child on a set day. Teachers saw this as a reasonable request from the health department, so it went ahead in thousands of schools without debate."}], "mech": "Teachers did not need to be persuaded, because giving a tablet on health advice fell inside what they expect the health department to decide. The zone of acceptance is about which decisions people see as the decider's to make. Inside it, a clear instruction is enough. The same department telling teachers how to teach reading would have met resistance. Because every school acted on the same day, coordination helped too: absent children could be caught on one mop-up day.", "ice": [{"tone": "good", "layers": [["What everyone sees", "Every school gives the tablets on the same day."], ["The pattern over time", "Instructions of this kind are carried out without debate."], ["The structure causing it", "The health department sends one simple, clear instruction down the chain."], ["The belief holding it in place", "“Health checks are the health department's call.”"]]}], "why": "Chester Barnard argued in 1938 that each person has a zone within which they accept instructions without questioning them. Edwin Bridges applied this to schools: involving teachers in decisions inside their zone wastes their time, while decisions outside it, where teachers have a stake and expertise, need their involvement.", "remember": "Decide alone only what people already see as your call. Ask about the rest."}, "network_shape": {"scenes": [{"tone": "good", "case": "Polycentric governance", "text": "Four school clusters each organised their own teaching under a few shared standards. The clusters met every term, and no cluster sat at the centre. One cluster tried longer science blocks, and over the next year the idea spread to two others because the results were good."}, {"tone": "bad", "case": "Slime mould networks", "text": "A student council closed the lunchtime peer groups that rarely met, including a group of three for students new to the country. In spring, two students arrived mid-year with little English. With no group to join, they spent lunchtimes alone for weeks."}], "mech": "Who talks to whom decides which ideas travel and how fast. In the clusters, every group talked to every other, so an idea moved on its merits, not because one group pushed it. For the peer groups, closing a quiet group removed the only route into the school for students new to the country. Other groups still existed, but the new students had no link to any of them. Network shape is about the routes between people, not about what each person knows.", "ice": [{"tone": "good", "layers": [["What everyone sees", "A good idea spreads from one cluster to others."], ["The pattern over time", "Ideas travel on their results, not on who backs them."], ["The structure causing it", "Every cluster meets every other, and none is at the centre."], ["The belief holding it in place", "“We learn from each other as equals.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "Two new students eating lunch alone."], ["The pattern over time", "Newcomers take weeks to find anyone to talk to."], ["The structure causing it", "The only group linking new arrivals to the school was closed because it was rarely used."], ["The belief holding it in place", "“If a group is rarely used, we don't need it.”"]]}], "why": "Becker, Brackbill and Centola asked groups to make estimates and then see the estimates of the people they were connected to. When everyone had the same number of connections, the groups became more accurate. When one person sat at the centre, the group drifted toward that person's estimate, whether it was right or wrong.", "remember": "Map who talks to whom, and protect the links that matter rarely but greatly."}, "homophily": {"scenes": [{"tone": "good", "case": "One person decides (autocratic)", "text": "A chemistry teacher assigned lab pairs herself instead of letting students choose. She explained that she was pairing careful workers with students who needed support. Some students grumbled about not working with friends, but no one was left until last."}, {"tone": "bad", "case": "Advice process", "text": "A principal wanted advice on a new behaviour policy. She asked her two deputies and the behaviour lead, the people she worked with every day. The special education coordinator, teachers' representatives and parents were never asked. The three advisers already shared her view of discipline, and the policy leaned on more suspensions."}], "mech": "People drift toward others like them, because it feels easy and trust is already there. In the lab, students left to choose would have paired with friends, and the same few would have been picked last. The teacher's list overrode that pull. The principal did not set out to exclude anyone. She asked the people nearest to her, and they were people like her. Homophily is about who ends up in the room. Once that circle had formed, groupthink did the rest: no one in it pushed back on more suspensions.", "ice": [{"tone": "good", "layers": [["What everyone sees", "Everyone has a lab partner, and no one is picked last."], ["The pattern over time", "Pairs mix students who would not choose each other."], ["The structure causing it", "The teacher assigns the pairs instead of letting students choose."], ["The belief holding it in place", "“Mixing people is part of my job.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "A policy written without the people it affects most."], ["The pattern over time", "The same few people advise on every decision."], ["The structure causing it", "The decider chooses whom to ask, and nothing checks who was left out."], ["The belief holding it in place", "“The people I trust are the right people to ask.”"]]}], "why": "McPherson, Smith-Lovin and Cook reviewed more than a hundred studies of friendships, marriages, work ties and advice networks. In almost all of them, people's ties were sorted by age, education, occupation and values. Information that flows through these ties tends to stay inside groups of similar people.", "remember": "Check who you asked. Then ask someone unlike them."}, "influence_few": {"scenes": [{"tone": "good", "case": "Futarchy", "text": "A school's leadership team used a points market to predict which of two reading programmes would help more Year 8 students read at their age level. Teachers who worked with weak readers bet heavily on the small-group programme, and the market moved toward it. The school chose it, and by June more students were reading at their age level than the market had predicted."}, {"tone": "bad", "case": "Nemawashi", "text": "A principal planned to merge two after-school clubs. She talked it through with the vice-principal, the senior club adviser and the PTA executive, and all of them agreed. No one visited the teacher who coached the smaller club, or its parents. At the staff meeting the merger was presented as settled, and that term the smaller club's members drifted away."}], "mech": "In both cases a few people shaped the outcome for everyone. In the market, the few were the teachers who knew most about weak readers, and they had the most reason to bet. Everyone else followed the price, so the group followed real expertise. In the club merger, the few were the people the principal chose to visit. Their agreement became the school's position before the meeting began. Influence from a few is about who others take their cue from. It helps when those few know most, and hurts when they are simply the best connected.", "ice": [{"tone": "good", "layers": [["What everyone sees", "The school picks the programme that works."], ["The pattern over time", "The price moves toward the people who know most."], ["The structure causing it", "Anyone can bet, and those who know most have most reason to."], ["The belief holding it in place", "“Back what you know, and watch what the experts back.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "The merger is announced as settled."], ["The pattern over time", "The same senior people are asked first, every time."], ["The structure causing it", "The principal decides whom to visit, and in what order."], ["The belief holding it in place", "“If the senior people agree, the matter is decided.”"]]}], "why": "Katz and Lazarsfeld studied how women in an American town formed views on shopping, fashion, films and politics. Most were not swayed directly by newspapers or radio. They took their cue from a few people around them who followed those topics closely. Ideas flowed from the media to these opinion leaders, and from them to everyone else.", "remember": "Notice whose view everyone is waiting for, and ask whether they know most."}, "conformity": {"scenes": [{"tone": "good", "case": "Herd movement", "text": "After the opening ceremony, 600 students had to move to their sports-day fields. A few marshals who knew the way were spread through the crowd. Students near each marshal followed them, the students near those followed in turn, and the whole crowd reached the right fields without an announcement."}, {"tone": "bad", "case": "Show of hands vote", "text": "A class elected its representative by show of hands. The popular student's friends at the front raised their hands first. Students who preferred the other candidate raised their hands anyway, to avoid standing out, and the popular student won easily."}], "mech": "People tend to do what those around them are doing. In the crowd, that habit was put to use: following the people nearby meant following someone who knew the way. In the class vote, the same habit hid what students thought. Raising a hand with everyone else was easier than being one of a few hands for the other candidate. Conformity is about going along in public. It is not the same as being persuaded, which is why several students later said they would have chosen the other candidate.", "ice": [{"tone": "good", "layers": [["What everyone sees", "The whole crowd reaches the right fields."], ["The pattern over time", "Students follow the people next to them."], ["The structure causing it", "Informed marshals are spread through the crowd, not only at the front."], ["The belief holding it in place", "“If the people near me are going this way, it must be right.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "A clear win for the popular student."], ["The pattern over time", "Class votes keep going to whoever the front rows back."], ["The structure causing it", "Votes are cast in public, in front of classmates."], ["The belief holding it in place", "“Standing out in this class is risky.”"]]}], "why": "In Solomon Asch's experiments, people matched the length of lines after hearing others in the room give an obviously wrong answer. About a third of all answers went along with the wrong group. When just one other person gave the right answer, conformity fell sharply.", "remember": "Collect disagreement in private before you count agreement in public."}, "cumulative": {"scenes": [{"tone": "good", "case": "Stigmergy (ant trails)", "text": "A maths department kept a shared bank of practice questions. After using one, each teacher ticked it and noted whether students got it. Questions that worked gathered ticks and rose to the top, so they were used more, and weak ones sank. By the end of term the bank had sorted itself."}, {"tone": "bad", "case": "Stigmergy (ant trails)", "text": "Teachers shared lesson-plan templates in a shared folder. The first template had a mistake in it. Because it was there first, it was copied most, and the most copied template was the one new staff copied next. Two years later most lesson plans in the school had the same flawed section."}], "mech": "In both cases, whatever was used most became easier to see, and so got used even more. In the question bank, the ticks recorded what worked, so the snowball grew around the best questions. In the folder, the first template had only a head start, not a better design, and the snowball grew around a mistake. Cumulative advantage is about how visibility turns small early leads into large final ones. Whether that helps depends on whether the early lead was earned.", "ice": [{"tone": "good", "layers": [["What everyone sees", "The questions that work are used most."], ["The pattern over time", "Questions with more ticks gather more ticks."], ["The structure causing it", "Every teacher records how a question went, where the next teacher can see it."], ["The belief holding it in place", "“If it worked in other classes, it will probably work in mine.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "Most lesson plans share the same flaw."], ["The pattern over time", "The first template is copied most, so it is copied next."], ["The structure causing it", "Templates are shown by how often they are used, and no one checks them."], ["The belief holding it in place", "“The most used template must be the approved one.”"]]}], "why": "Salganik, Dodds and Watts set up an online music market with more than 14,000 participants. In some versions, people could see how often each song had been downloaded. In those versions, popular songs became far more popular, and which songs came top varied widely from one version to the next. The best songs rarely did badly, but the rest of the ranking was largely luck.", "remember": "Before you copy what is popular, check that it was ever good."}, "polarization": {"scenes": [{"tone": "good", "case": "Indaba", "text": "A school held a fishbowl discussion on phones. A small circle of students, teachers and parents talked while everyone else listened. Anyone who rejected an idea had to offer another in its place. The talk moved toward a plan that every group could live with, and because everyone watched it happen, the school accepted it."}, {"tone": "bad", "case": "Unanimous consensus with discussion", "text": "A community school had to decide whether to accept a grant that came with extra testing. Most members wanted the money, and two opposed the testing. Each meeting repeated the same arguments, and both camps grew more certain. No one looked for a middle way, such as accepting with conditions, and the school lost the grant."}], "mech": "When people mainly hear arguments for their own side, their views move further in the direction they already leaned. In the grant meetings, each camp heard its own arguments again and again, and each meeting left both more certain. In the fishbowl, the rule that every no comes with an idea meant people had to engage with what others needed, so views moved toward each other instead. Polarization is about views getting more extreme through discussion. It is not the same as people simply disagreeing.", "ice": [{"tone": "good", "layers": [["What everyone sees", "A phone plan the whole school accepts."], ["The pattern over time", "Each objection leads to a new idea, and the plan improves."], ["The structure causing it", "A rule that every no must come with an alternative."], ["The belief holding it in place", "“My job is to find something that works for everyone.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "The school loses the grant."], ["The pattern over time", "Each meeting repeats the same arguments, and both sides harden."], ["The structure causing it", "More meetings, with no new information and no fallback rule."], ["The belief holding it in place", "“If we argue long enough, they will see we are right.”"]]}], "why": "Myers and Lamm reviewed many studies in which groups discussed a question and then gave their views again. After discussion, groups usually moved further in the direction most members had leaned at the start. Cass Sunstein called this the law of group polarization, and found it in juries, panels of judges and online groups.", "remember": "Ask every critic for an alternative, not only an objection."}, "commitment": {"scenes": [{"tone": "good", "case": "Conviction voting", "text": "Teachers used conviction voting to decide how students may use AI. Support for a policy built up the longer teachers kept it there, and a policy was adopted only once support had lasted. A wave of alarm after one news story faded before it could pass anything, and the policy that passed was one teachers had stuck with for months."}, {"tone": "bad", "case": "Conviction voting", "text": "Students used the same system to back proposals for the school's club fund. Most placed their support in September and never changed it. Their old choices kept building, and by the time the film club was funded, most of its backers had lost interest."}], "mech": "Both cases reward people for sticking with a choice. For the AI policy, that was the point: teachers were trying the tools for themselves, and staying with a view for months showed it rested on experience, not on one week's news. For the club fund, sticking with a choice took no effort at all, so September's choices kept counting after the reasons had gone. Commitment is about continuing with a choice because you have already made it. It helps when people keep checking that the reasons still hold, and hurts when the choice carries on without anyone looking. Here it hurt partly because students had stopped taking part, which is exit at work.", "ice": [{"tone": "good", "layers": [["What everyone sees", "A policy on AI that teachers keep to."], ["The pattern over time", "Support grows only for views that last."], ["The structure causing it", "Support builds up slowly, and a policy passes only once it has lasted."], ["The belief holding it in place", "“A view I still hold after months is worth counting.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "Funding goes to a club few still want."], ["The pattern over time", "Old choices keep counting long after interest has moved on."], ["The structure causing it", "Support carries on by itself unless someone changes it."], ["The belief holding it in place", "“I already chose, so there is nothing more to do.”"]]}], "why": "Barry Staw asked business students to act as managers and give money to one of two company divisions. When their chosen division then did badly, they put more money into it than students who had inherited the same failing choice from someone else. Having made the choice themselves, they kept backing it.", "remember": "Ask whether you would still choose this today, if you were starting fresh."}, "spiral_silence": {"scenes": [{"tone": "bad", "case": "One person decides (autocratic)", "text": "A school's owner raised fees by 15% overnight, by message. A few parents complained loudly. The families who could not afford the rise stayed quiet, worried their child would be treated differently. Two weeks later twelve families asked for transfer certificates."}], "mech": "Each struggling family looked around and saw only a few complaints, so they concluded that most families could pay and they were the odd ones out. Feeling in the minority, they kept quiet, which made the objections look even smaller to the next family. In fact many were in the same position. Spiral of silence is about people going quiet because they think they are in the minority, and that silence shrinking the minority further. Here the families had a second reason to stay quiet, fear for their child, and with no safe way to object, many left instead. That is exit at work.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "A few complaints, then twelve families leave."], ["The pattern over time", "Objections look smaller than they are, and more people stop raising them."], ["The structure causing it", "No safe way to object, and complaints are only visible when made in public."], ["The belief holding it in place", "“Everyone else can manage this. I'm the only one who can't.”"]]}], "why": "Elisabeth Noelle-Neumann found that people constantly judge which views are gaining or losing ground, and that those who think their view is losing are less willing to say it in public. Morrison and Milliken found the same inside organisations: when staff believe speaking up is risky or pointless, silence spreads, and the people at the top hear less and less.", "remember": "Give people a private way to object, and count the quiet ones."}, "exit_voice": {"scenes": [{"tone": "bad", "case": "Weighted voting", "text": "Four schools shared a budget, with votes weighted by how many pupils each had. The largest school had more than half the weight, so its vote alone passed every proposal. The three small schools stopped sending anyone to meetings, and from then on the board heard only from the large school."}], "mech": "The small schools had two options when they were unhappy: argue for change, or stop coming. Arguing could never change a vote, so they stopped coming. Exit is quiet. No one complained, so the board had no warning that the arrangement was failing until it was already empty. Exit and voice is about which of the two people choose. They choose exit when voice feels risky or pointless.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "The small schools stop coming to meetings."], ["The pattern over time", "Fewer voices each term, and no complaints."], ["The structure causing it", "Votes are weighted so one school can always win."], ["The belief holding it in place", "“Speaking up here changes nothing.”"]]}], "why": "Albert Hirschman described two ways people respond when an organisation gets worse: they leave, or they speak up. He noted that the people most able to speak up are often the first to leave. When a public school declines, the parents best placed to push for improvement are often the first to move their children elsewhere.", "remember": "If people stop complaining, check whether they have stopped coming."}, "cascade": {"scenes": [{"tone": "good", "case": "Herd movement", "text": "On sports day, 600 students had to move from the opening ceremony to their fields. A few marshals who knew the way were spread through the crowd. Students followed whoever was moving near them, and because the first to move were marshals, each student who followed was copying a correct choice."}, {"tone": "bad", "case": "Herd movement", "text": "Students arrived for an exam in an unfamiliar building with unclear signs. The first few set off confidently toward the wrong hall. Each student who followed made that direction look more certain to the next arrival. Students who had doubts kept walking, and the exam started late for all of them."}], "mech": "Copying works when the first people to choose know the answer: on sports day they were marshals, so following them was the quickest route. It fails when the first choices are guesses. At the exam, each student had some private clue, such as a room number or a vague memory of the building. But seeing many others heading one way seemed like stronger evidence than their own clue, so they followed. Once enough people had done that, the crowd's direction told newcomers nothing: it reflected only the first few choices. A cascade is about copying others because their choices look like information. It differs from conformity, where people go along to avoid standing out, but here both were at work: the doubters also did not want to stop alone.", "ice": [{"tone": "good", "layers": [["What everyone sees", "600 students reach the right fields quickly."], ["The pattern over time", "Each student follows the people moving near them."], ["The structure causing it", "Marshals who know the way are spread through the crowd."], ["The belief holding it in place", "“The people ahead of me know where they are going.”"]]}, {"tone": "bad", "layers": [["What everyone sees", "A crowd of students at the wrong hall."], ["The pattern over time", "Each arrival follows the crowd, and the crowd keeps growing."], ["The structure causing it", "Unclear signs, and everyone can see which way others went."], ["The belief holding it in place", "“So many people can't all be wrong.”"]]}], "why": "Bikhchandani, Hirshleifer and Welch showed that once the first few people choose the same way, it becomes sensible for each later person to copy them, whatever they privately know. A whole line of people can then end up wrong because of two or three early choices. They also showed that such cascades are fragile: a little clear public information can reverse them.", "remember": "Ask what people know, not only what they chose."}, "groupthink": {"scenes": [{"tone": "bad", "case": "Futarchy", "text": "A foundation funding literacy programmes in Ghana voted to fund whichever programme would raise reading test scores most. The board treated test scores as the obvious measure, and no one was asked to argue that scores might miss the point. Scores rose, but teachers reported less time for storytelling and local-language reading, and children did no better the following year."}], "mech": "Test scores were the measure everyone already used, so questioning them felt like questioning the group. No one was given the job of arguing the other side, so no one did. Groupthink is about a cohesive group protecting its agreement. The board was not short of information. It simply never put its shared assumption to the test.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "Test scores rise, and children read no better."], ["The pattern over time", "The board agrees quickly, and no one questions the measure."], ["The structure causing it", "No one is given the job of arguing against the group's view."], ["The belief holding it in place", "“We all know what good reading looks like.”"]]}], "why": "Irving Janis studied foreign-policy failures such as the Bay of Pigs invasion. He found close groups that rushed to agree, kept their doubts to themselves, and took silence as consent. He also studied the Cuban missile crisis, where the same president had advisers argue against each other on purpose, and the group decided far better.", "remember": "Ask someone to argue the other side, especially when everyone agrees."}, "mum_effect": {"scenes": [{"tone": "bad", "case": "Chain of command", "text": "A teacher raised a complaint about her workload with her head of department, and it was passed up the chain by word of mouth. No one wanted to tell their manager that a colleague was struggling, so each level passed on a gentler version. By the time it reached the principal it sounded routine. Nothing changed, and the teacher started applying for other jobs."}], "mech": "No one lied. At each step, someone had to pass bad news to a person with power over them, and each chose a softer version that would not reflect badly on them or their team. The mum effect is about holding back bad news from the people above you. It was made worse by message drift: with nothing in writing, each level heard only the version from the level below. And when nothing changed, the teacher chose exit.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "The principal hears a routine complaint."], ["The pattern over time", "Bad news gets softer at every level."], ["The structure causing it", "Each level is judged on how calm things look, and there is no direct route to the top."], ["The belief holding it in place", "“Passing this on will make me look bad.”"]]}], "why": "Rosen and Tesser found that people were far more willing to pass on good news than bad news to the person it concerned. They called this reluctance the mum effect, and later studies found it is strongest when the receiver has power over the messenger.", "remember": "Ask for bad news directly, and thank the people who bring it."}, "message_drift": {"scenes": [{"tone": "bad", "case": "Chain of command", "text": "A teacher's workload complaint passed up to the principal by word of mouth. Each level heard only the version from the level below, with nothing in writing. At each step it was retold from memory, a little shorter and more general, and no one could see how much it had changed. By the time it reached the principal it sounded routine."}], "mech": "Each person passed on what they remembered, and what they remembered was the gist, shaped by what they expected a workload complaint to sound like. The specific details, which were the reason it mattered, were the first to go. Message drift is about how a message changes as it is retold, even when no one means to change it. Here it combined with the mum effect: each level also wanted the news to sound milder.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "The principal hears a mild, general complaint."], ["The pattern over time", "The message gets shorter and more general at each step."], ["The structure causing it", "The complaint is passed on by word of mouth, with nothing in writing."], ["The belief holding it in place", "“I've passed on the main point.”"]]}], "why": "Frederic Bartlett asked people to read an unfamiliar folk tale and retell it from memory, then passed each retelling to the next person. With each retelling the story grew shorter, unfamiliar details dropped out, and what remained was changed to fit what the reader already expected.", "remember": "Pass concerns on in the original words, in writing."}, "diffusion": {"scenes": [{"tone": "bad", "case": "Sociocratic consent and holacracy", "text": "A leadership team took every decision to a full consent round, however small. Meetings ran long, and no one had the authority to act between them. When an urgent day-to-day matter came up, each member assumed it would be handled at the next round, so it waited."}], "mech": "Every member could see the problem, and any of them could have raised it. But because the decision belonged to the whole team, it felt like no one's in particular, so each waited for the team. Diffusion of responsibility is about each person feeling less responsible because others could act too. The consent process itself was sound for policy. The trouble was using it for every day-to-day matter, with no one named to act between meetings.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "Urgent matters wait for the next meeting."], ["The pattern over time", "Urgent matters pile up, and meetings get longer."], ["The structure causing it", "Every decision goes to a full round, and no one can act between meetings."], ["The belief holding it in place", "“The team will deal with it.”"]]}], "why": "Darley and Latané had students talk over an intercom, and one apparently had a seizure. Students who thought they were the only listener almost all went for help. Students who thought four others were listening were far less likely to, and slower when they did.", "remember": "Name one person to act on each kind of urgent matter."}, "blame_avoidance": {"scenes": [{"tone": "bad", "case": "Citizens’ assembly", "text": "A government asked citizens drawn by lot to rethink the school day. It promised only that the proposals would inform its thinking. Teachers' unions, whose members would have to carry out the changes, rejected them. A year later none had been taken up, and the government had never had to say no."}], "mech": "Adopting the proposals meant owning a fight with the unions. Rejecting them meant being blamed for ignoring the citizens. Leaving them as advice let the government avoid both. Blame avoidance is about choosing the option that is safest to defend, not the best one. It was possible because accountability was weak: nothing required ministers to answer each recommendation, or to do it by a date.", "ice": [{"tone": "bad", "layers": [["What everyone sees", "The proposals quietly disappear."], ["The pattern over time", "Hard recommendations stay as advice and are never acted on."], ["The structure causing it", "The government keeps the final say, with no duty to answer or deadline."], ["The belief holding it in place", "“Doing nothing is the safest choice.”"]]}], "why": "Kent Weaver argued that politicians work harder to avoid blame than to earn credit, because voters punish losses more than they reward gains. Christopher Hood described the main ways they do it: presenting decisions so they look unavoidable, passing them to someone else, and choosing policies no one can be blamed for.", "remember": "Before you start, agree who must answer the result, and by when."}},
when:{"cascade": ["When the first people to act are the ones who know, such as guides or marshals placed in a crowd.", "When there is no time to ask, and copying informed people is quicker than explaining."], "independent": ["Estimates and forecasts: the average of independent guesses is often better than any single expert's.", "Early in a decision, before anyone has anchored the group."], "fair_process": ["When the outcome will disappoint some people, such as budget cuts or admissions.", "When people must carry out a decision they didn't choose."], "coordination": ["When it matters more that everyone does the same thing than which thing it is, such as a bell schedule or a shared format.", "When a settled routine frees time for harder questions."], "local_knowledge": ["When a problem shows up in classrooms, corridors or homes before it shows up in data.", "When a plan has to work on the ground, not just on paper."], "accountability": ["When a decision is complex and several views need weighing.", "When people know in advance who they will have to explain it to."], "zone_acceptance": ["For routine, clearly delegated decisions that don't need debate every time.", "In an emergency, when someone has to act at once."], "shared_info": ["When everyone needs the same facts, so the argument is about choices, not figures.", "After a decision, so everyone knows what was agreed."], "influence_few": ["When the few are the people who really know, such as the special needs coordinator on support plans.", "When a trusted person brings others round to a change that has already been agreed."], "network_shape": ["When well-connected people spread news or a good practice fast.", "When people who bridge two groups bring in ideas the group lacks."], "conformity": ["When shared norms, such as how people treat each other, keep a school safe and kind.", "When newcomers need to learn the routines quickly."], "polarization": ["When a group needs a clear, shared position to act on, such as a staff response to a proposal.", "When discussion turns quiet, scattered concern into a confident stand."], "cumulative": ["When early success draws support to something that really is good.", "When a small new initiative needs momentum to survive."], "homophily": ["When people need trust and ease to work fast, such as a small planning team.", "When a minority group needs a space of its own to find its voice."], "commitment": ["When a good plan needs time to work, and early results are naturally weak.", "When getting through a hard patch is the point, such as a new reading programme."]},
symptoms:[
  {s:"Everyone agreed in the meeting, but nothing changed afterwards.", f:["pluralistic_ignorance","spiral_silence"]},
  {s:"The first person to speak set the direction for everyone.", f:["cascade","conformity"]},
  {s:"The same few people always end up deciding.", f:["influence_few","network_shape"]},
  {s:"People complain in the corridor but not in meetings, or quietly leave.", f:["spiral_silence","exit_voice"]},
  {s:"We keep defending a plan that isn't working.", f:["commitment","groupthink"]},
  {s:"Bad news reached the head too late, or softened.", f:["mum_effect","message_drift"]},
  {s:"Everyone assumed someone else would deal with it.", f:["diffusion"]},
  {s:"The group came out more extreme than anyone went in.", f:["polarization","homophily"]},
  {s:"People accepted a decision they disliked, or rejected one they might have liked.", f:["fair_process","zone_acceptance"]},
  {s:"The people closest to the problem were never asked.", f:["local_knowledge","influence_few"]},
  {s:"Everyone made the same mistake, because everyone relied on the same information.", f:["shared_info","independent"]},
  {s:"An early favourite kept winning, even after better options appeared.", f:["cumulative","cascade"]},
  {s:"We chose the obvious option because we expected everyone else to.", f:["coordination"]},
  {s:"Decisions got careless when no one had to explain them.", f:["accountability"]},
  {s:"We hid behind policy, or someone junior took the blame.", f:["blame_avoidance","diffusion"]},
  {s:"A good idea was dropped because no one wanted to own it.", f:["blame_avoidance"]}
],
guide:{
  independent:{spot:["People form views before hearing anyone else.","Answers differ, sometimes a lot, before discussion starts."],
    help:[["Ask people to write their view before discussing","ngt"],["Collect estimates or ratings privately first","delphi"],["Hear junior people before senior ones","stepladder"]]},
  shared_info:{spot:["Everyone quotes the same report, figure or person.","Surprises appear only after the decision."],
    help:[["Share the full facts, costs and options with everyone","frame_question"],["Ask what each person knows that others might not","go_around"],["Check who is missing and ask them","stakeholders"]]},
  influence_few:{spot:["The same names come up as \"what people think\".","Meetings confirm what was agreed elsewhere."],
    help:[["Give everyone a turn before open discussion","go_around"],["Gather ideas in writing, so volume doesn't count","ngt"],["Cap any one voter's weight, or use a supermajority",""]]},
  network_shape:{spot:["Some people hear about decisions long after others.","Information travels through one or two people."],
    help:[["Check who is missing from the conversation","stakeholders"],["Put people who know the facts in every part of the group",""],["Map who talks to whom before a big change",""]]},
  cascade:{spot:["Later speakers agree with earlier ones more than you'd expect.","The order of speaking seems to decide the outcome."],
    help:[["Ask for views at the same moment, in writing or by show of cards","gradients"],["Write ideas alone before sharing","ngt"],["Ask the most senior person to speak last","stepladder"]]},
  cumulative:{spot:["The option that got an early lead keeps growing, whatever its quality.","The most copied version is the oldest, not the best."],
    help:[["Check the most popular option on its merits","criteria"],["Agree criteria before seeing which option is popular","criteria"],["Fix or remove early versions once a better one exists",""]]},
  conformity:{spot:["Unanimous agreement after a short discussion.","People agree in public and disagree in private."],
    help:[["Collect views in private before discussing","ngt"],["Assign someone to argue the other side","debate"],["Ask people to answer in turn, out loud","go_around"]]},
  coordination:{spot:["People choose the obvious option because they expect others to.","No one is sure the choice is good, only that it is shared."],
    help:[["Say openly which options are on the table","frame_question"],["Give people time to propose alternatives","brainstorming"]]},
  groupthink:{spot:["Doubts are raised outside the meeting, not in it.","The group sees critics as disloyal."],
    help:[["Run a pre-mortem before committing","premortem"],["Invite an outsider to review the proposal","stakeholders"],["Assign a devil's advocate","debate"]]},
  spiral_silence:{spot:["The same few people speak, and others stay silent.","People tell you their real view afterwards, one to one.","People complain in the corridor but not in meetings."],
    help:[["Ask for concerns in writing or anonymously","ngt"],["Talk to people one to one before the meeting","nemawashi"],["Thank people who disagree, in public",""]]},
  pluralistic_ignorance:{spot:["Everyone seems to agree, but nothing changes.","Private conversations contradict the public view."],
    help:[["Show how strongly people really agree, all at once","gradients"],["Use anonymous polls or opinion mapping","polis"],["Ask directly: who has doubts about this?",""]]},
  polarization:{spot:["The group ends up more extreme than its members started.","People who disagree stop coming."],
    help:[["Bring in people with different views before deciding","stakeholders"],["Move from positions to the needs behind them","needs"],["Require every no to come with another idea",""]]},
  zone_acceptance:{spot:["People accept the decision without question because it is the decider's call.","Questions only come when a decision falls outside what people expect."],
    help:[["Say clearly who decides and why","frame_question"],["For decisions outside the usual, consult first",""]]},
  fair_process:{spot:["People reject a good decision because they weren't heard.","People accept a hard decision because they understood how it was made."],
    help:[["Say at the start how the decision will be made","frame_question"],["Explain the reasons for the final decision",""],["Show how concerns changed the proposal","tuners"]]},
  homophily:{spot:["Working groups are made up of friends or people alike.","New ideas rarely come from the usual group."],
    help:[["Mix groups on purpose","charrette"],["Check who is missing","stakeholders"]]},
  exit_voice:{spot:["People leave or stop coming instead of complaining.","Exit interviews reveal problems no one raised."],
    help:[["Make speaking up safe and easy, including anonymously",""],["Ask newcomers and quieter members directly","go_around"],["Act visibly on concerns that are raised",""]]},
  local_knowledge:{spot:["Plans fail on details the people doing the work could have predicted.","Those closest to the problem hear about the decision last."],
    help:[["Ask the people closest to the problem first","stakeholders"],["Test the plan with them before deciding","premortem"]]},
  commitment:{spot:["The plan's backers explain away every bad result.","Stopping feels like admitting a mistake.","More money or time goes in because so much already has."],
    help:[["Set review dates and stopping rules at the start","frame_question"],["Ask someone not involved to review progress",""],["Run a pre-mortem, then check against it","premortem"]],
    ex:"A school keeps paying for a reading programme for a third year because it has already trained every teacher in it, even though test results have not improved."},
  accountability:{spot:["Decisions improve when people know they must explain them.","Without anyone to answer to, decisions get careless."],
    help:[["Agree who will explain the decision, and to whom","frame_question"],["Record who raised which concern and how it was answered",""]]},
  mum_effect:{spot:["The head is the last to hear about problems.","Bad news arrives softened, or late."],
    help:[["Thank people for bad news",""],["Ask directly: what is going wrong?","go_around"],["Let people report problems anonymously",""]]},
  message_drift:{spot:["A decision means different things in different departments.","Instructions get shorter and simpler as they pass down."],
    help:[["Write the decision down and send it to everyone at once",""],["Ask people to say back what they understood",""]]},
  blame_avoidance:{spot:["Deflect: \"It's the board's policy\" or \"the consultants recommended it\", or someone junior takes the fall.","Distract: bad news is spun, or released when no one is paying attention, such as the last day of term.","Decline: a good idea is dropped because whoever backs it would be blamed if it failed.","Diffuse: a decision is shared so widely that no one can be held to account."],
    help:[["Name one owner for each decision, and record the reasons",""],["Set review dates, so a failure can be fixed without a hunt for someone to blame",""],["Treat honest mistakes as information, not as grounds for punishment",""]]},
  diffusion:{spot:["Everyone noticed a problem, and no one acted.","Several people share a task, and no one owns it."],
    help:[["Name one person for each task","who_what_when"],["Ask: who will do this, by when?","who_what_when"]]}
}
};
